/**
 * CSV の1行目のフィクスチャ（契約 `docs/contracts/slice-csv-headerguard.md`・スライスCH）。
 *
 * **実データを1つも置かない。** 2026-08-31 の事故で Anthropic API に送られたのは
 * 銀行名・支店名・口座番号・口座名義であり、それらは**形だけを写して値は架空にする**
 * （契約の停止点）。守りたいのは「どんな形が来ると判定が false になるか」であって、
 * 誰の口座かではない。
 *
 * 判定に使うのは**数値・日付・空の3つだけ**（CH-D5）。半角カナは使わない。
 * したがってカナの中身を架空にしても、判定の再現性は1ミリも落ちない。
 */

/**
 * 全銀協規定フォーマット系の入出金明細の1行目（**列名の行が無い**形）。
 *
 * 実物と同じ **17列・うち14が数値/日付/空** の形にしてある（報告書
 * `docs/reports/2026-08-31_CSV_ヘッダー行前提が崩れる.md` の実測）。
 * カナ3つ（銀行名・科目名・口座名義）だけが「列名らしい」側に数えられる。
 */
export const ZENGIN_FIRST_ROW = [
  "1",
  "3",
  "0",
  "80830",
  "80301",
  "80830",
  "310",
  "ｼﾞ-ｴﾑｵ-ﾃｽﾄ", // 銀行名。実物ではない
  "102",
  "ﾎｳｼﾞﾝﾀﾞｲﾆ",
  "0",
  "1",
  "9999999", // 口座番号。実物ではない
  "ｶ)ﾃｽﾄ", // 口座名義。実物ではない
  "1",
  "", // 空欄
  "123821",
];

/** 銀行入出金明細の列名（CH-2-1。2026-08-31 に本番で 200 になった形） */
export const BANK_HEADER_ROW = ["取引日", "摘要", "お支払金額", "お預り金額", "差引残高"];

/** Stripe 入金レポートの列名（CH-2-2） */
export const STRIPE_HEADER_ROW = ["created", "description", "amount", "fee", "net", "type"];

/** 弥生仕訳日記帳の列名（CH-2-3） */
export const YAYOI_HEADER_ROW = ["仕訳日付", "借方金額", "貸方金額", "摘要"];

/**
 * 列名に年月が混ざる形（CH-2-4）。**閾値の意味を固定する境界**である。
 * `2026年8月` を日付と数えると 2/3 で落ちてしまうが、これは**列名として正しい**。
 * 年月（日が無い）を日付と見なさない判断は `shared/csv/header-guard.ts` に書いてある。
 */
export const MONTHLY_HEADER_ROW = ["項目", "2026年8月", "2026年9月"];

/**
 * あおぞら銀行の**列名付き**入出金明細の列名（CH-2-5）。**実物である**
 * （2026-09-01、梶谷さんが実ファイルの1行目を確認して提供）。
 *
 * 2026-08-31 の時点では実物が確認できず `_PLACEHOLDER` を付けた架空の値を置いていた。
 * **架空の値なのにテストが緑になる**状態を名前で見えるようにするためである
 * （`.claude/rules/ci-coverage.md` が言う「検査の空洞」と同じ形）。実物に差し替えたので外した。
 *
 * 実ファイルの性質（梶谷さん確認・**明細の中身はここに書かない**）:
 *
 * - 文字コードは **Shift-JIS**。`connect-client.tsx` の
 *   `TextDecoder("shift_jis", { fatal: true })` → UTF-8 フォールバックで正しくデコードされる
 * - **6列・カンマ区切り・全フィールドがダブルクォート囲み**
 * - 60行（列名1 + 明細59）。本番の「明細 59件」と一致する
 * - 明細の型は 数値 / 文字列 / 数値or空 / 数値or空 / 数値 / 文字列。
 *   入金金額と出金金額は**どちらか一方が必ず空**になる
 *
 * 判定に照らすと **6列すべてが文字列**なので、
 * 「数値のみ・日付・空」は 0/6 で、余裕を持って列名の行と判定される。
 */
export const AOZORA_HEADER_ROW = ["日付", "摘要", "入金金額", "出金金額", "残高", "メモ"];

/**
 * 同じ行の**生テキスト**（全フィールドがダブルクォート囲み）。
 *
 * 実ファイルは全フィールドが引用符で囲まれているので、`parseCSVLine` が
 * それを外したうえで判定に渡っていることまで確かめる。
 * **明細行は含めない**（列名の行だけで足りる）。
 */
export const AOZORA_HEADER_LINE = '"日付","摘要","入金金額","出金金額","残高","メモ"';

/**
 * **生のCSVテキスト**のフィクスチャ。実物が持っている厄介さを写してある。
 *
 * - **BOM** つき（銀行の書き出しに普通に付く）
 * - **CRLF** 改行
 * - **全セルがダブルクォート囲み**
 *
 * 手で組んだ配列だけで判定を試験すると、`parseCSVLine` の挙動が変わった日に
 * **テストは緑のまま本番だけ抜ける。** 生テキストから判定までを一本で通すために置く。
 * 値はすべて架空である（契約の停止点）。
 */
export const ZENGIN_CSV_TEXT =
  '﻿"1","3","0","80830","80301","80830","310","ｼﾞ-ｴﾑｵ-ﾃｽﾄ","102","ﾎｳｼﾞﾝﾀﾞｲﾆ","0","1","9999999","ｶ)ﾃｽﾄ","1","","123821"\r\n' +
  '"2","80830","1","9999","ﾃｽﾄﾌﾘｺﾐ","123821","","","","","","","","","","",""\r\n';

/** 列名の行がある銀行入出金明細の生テキスト。こちらは**通らなければならない** */
export const BANK_CSV_TEXT =
  '﻿"取引日","摘要","お支払金額","お預り金額","差引残高"\r\n' +
  '"2026/08/01","ﾃｽﾄﾌﾘｺﾐ","","1,000,000","9,999,999"\r\n' +
  '"2026/08/02","ﾃｽﾄｼﾊﾗｲ","250,000","","9,749,999"\r\n';
